  function makeCat(){
    catFurMat=mat(0xc87636,.88);collarMat=mat(save.collar||0xff6b8b,.42,.1);
    catModel=createCatModel(T,{fur:catFurMat,collar:collarMat,patchMaterials:[mat(0xf3eee2),mat(0x302b32)]});
    cat.add(catModel.root);calicoPatches=catModel.patches;
    motion.add(cat,'cat',{...catModel,sprint:()=>keys.Shift});scene.add(cat);
  }
